INSERT OR IGNORE INTO surveys (id, title, slug, description, status, language, draft_definition, published_version_id, created_at, updated_at, published_at) VALUES ('srv_import_post_class', 'Post Class Survey', 'post-class-survey', 'Tell us what changed for you and how we can improve future diabetes education classes.', 'open', 'en', '{"title":"Post Class Survey","description":"Tell us what changed for you and how we can improve future diabetes education classes.","language":"en","defaultLanguage":"en","languages":["en","zh-CN","es"],"translations":{"zh-CN":{"title":"课程结束问卷","description":"请告诉我们课程给您带来了哪些改变，以及我们可以怎样改进今后的糖尿病教育课程。","thankYouTitle":"感谢您的反馈","thankYouMessage":"您的回答已经提交。","pages":{"page_1":{"title":"问卷问题","description":"","questions":{"instructor":{"title":"讲师解释得很清楚，也能有效回答我的问题。","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"非常不同意","scaleMaxLabel":"非常同意"},"understanding":{"title":"完成课程后，您如何评价自己对糖尿病的了解？","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"完全不了解","scaleMaxLabel":"非常了解"},"health_confidence":{"title":"现在，我有信心通过健康饮食、规律运动、按时用药和监测血糖来管理健康。","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"完全没信心","scaleMaxLabel":"非常有信心"},"healthy_habit":{"title":"我知道如何在日常生活中加入至少一种有助于控制血糖的健康习惯。","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"非常不同意","scaleMaxLabel":"非常同意"},"seek_support":{"title":"如果出现与糖尿病有关的问题，我知道如何寻求帮助和支持。","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"非常不同意","scaleMaxLabel":"非常同意"},"health_goal":{"title":"我已经为自己设定了至少一个具体的健康目标，并计划在下个月开始行动。","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"非常不同意","scaleMaxLabel":"非常同意"},"care_team":{"title":"我现在更愿意主动和医疗团队沟通自己的健康问题。","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"非常不同意","scaleMaxLabel":"非常同意"},"satisfaction":{"title":"总体来说，您对这次糖尿病教育课程有多满意？","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"非常不满意","scaleMaxLabel":"非常满意"},"helpful_session":{"title":"六节课中，哪一节对您帮助最大？","description":"","options":{"session_1":"第1节","session_2":"第2节","session_3":"第3节","session_4":"第4节","session_5":"第5节","session_6":"第6节"},"rows":{},"columns":{},"scaleMinLabel":"","scaleMaxLabel":""},"recommend":{"title":"您愿意把这门糖尿病教育课程推荐给家人或朋友吗？","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"不会推荐","scaleMaxLabel":"一定会推荐"}}}}},"es":{"title":"Encuesta posterior al curso","description":"Cuéntenos qué cambió para usted y cómo podemos mejorar futuros cursos de educación sobre la diabetes.","thankYouTitle":"Gracias por sus comentarios","thankYouMessage":"Sus respuestas se enviaron correctamente.","pages":{"page_1":{"title":"Preguntas","description":"","questions":{"instructor":{"title":"El instructor explicó con claridad y respondió eficazmente mis preguntas.","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"Totalmente en desacuerdo","scaleMaxLabel":"Totalmente de acuerdo"},"understanding":{"title":"Después del curso, ¿cómo calificaría su comprensión de la diabetes?","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"Ningún conocimiento","scaleMaxLabel":"Mucho conocimiento"},"health_confidence":{"title":"Ahora confío en cuidar mi salud mediante alimentación saludable, ejercicio regular, medicamentos a tiempo y control de glucosa.","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"Nada de confianza","scaleMaxLabel":"Mucha confianza"},"healthy_habit":{"title":"Sé cómo incorporar a mi vida diaria al menos un hábito saludable que ayude a controlar la glucosa.","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"Totalmente en desacuerdo","scaleMaxLabel":"Totalmente de acuerdo"},"seek_support":{"title":"Sé cómo buscar ayuda y apoyo si surge algún problema relacionado con la diabetes.","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"Totalmente en desacuerdo","scaleMaxLabel":"Totalmente de acuerdo"},"health_goal":{"title":"He establecido al menos una meta de salud específica y planeo comenzar a trabajar en ella durante el próximo mes.","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"Totalmente en desacuerdo","scaleMaxLabel":"Totalmente de acuerdo"},"care_team":{"title":"Estoy más dispuesto/a a hablar activamente con mi equipo de salud sobre mis inquietudes.","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"Totalmente en desacuerdo","scaleMaxLabel":"Totalmente de acuerdo"},"satisfaction":{"title":"En general, ¿qué tan satisfecho/a está con este curso de educación sobre la diabetes?","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"Muy insatisfecho/a","scaleMaxLabel":"Muy satisfecho/a"},"helpful_session":{"title":"¿Cuál de las seis sesiones le resultó más útil?","description":"","options":{"session_1":"Sesión 1","session_2":"Sesión 2","session_3":"Sesión 3","session_4":"Sesión 4","session_5":"Sesión 5","session_6":"Sesión 6"},"rows":{},"columns":{},"scaleMinLabel":"","scaleMaxLabel":""},"recommend":{"title":"¿Recomendaría este curso de educación sobre la diabetes a familiares o amigos?","description":"","options":{},"rows":{},"columns":{},"scaleMinLabel":"No lo recomendaría","scaleMaxLabel":"Sin duda lo recomendaría"}}}}}},"pages":[{"id":"page_1","title":"Questions","description":"","questions":[{"id":"instructor","type":"rating","title":"The instructor explained things clearly and answered my questions effectively.","description":"","required":false,"scaleMin":1,"scaleMax":5,"scaleMinLabel":"Strongly disagree","scaleMaxLabel":"Strongly agree"},{"id":"understanding","type":"rating","title":"After completing the course, how would you rate your understanding of diabetes?","description":"","required":false,"scaleMin":1,"scaleMax":5,"scaleMinLabel":"Not knowledgeable at all","scaleMaxLabel":"Very knowledgeable"},{"id":"health_confidence","type":"rating","title":"I am now confident in managing my health through healthy eating, r